/* Reduce OOTB widget button width */
.fm-custom-widget .btn {
    width: auto !important;
    min-width: 100px;
    padding: 6px 14px !important;
    display: inline-block !important;
}

/* Override full-width Bootstrap buttons */
.fm-custom-widget .btn-block {
    width: auto !important;
}
